I've assumed a React web app (works as a PWA); tell me if you'd rather have React Native or Flutter. It covers the full parent flow: choose children, tap **I'm here**, a one-time location check, a live per-child status, and cancel.

```tsx
// ParentPickupScreen.tsx
import { useEffect, useState } from "react";

/* ---------- Config ---------- */
const SCHOOL = { lat: 51.5007, lng: -0.1246 }; // TODO: your gate coordinates
const GEOFENCE_METERS = 150;
const MAX_ACCURACY_METERS = 100;
const POLL_MS = 4000;

/* ---------- Types ---------- */
type Child = { id: string; name: string; className: string };
type ChildStatus = "waiting" | "released";
type Phase = "idle" | "locating" | "sending" | "waiting" | "done";

class UserError extends Error {}

/* ---------- API (replace with real endpoints) ---------- */
const api = {
  async getChildren(): Promise<Child[]> {
    return (await fetch("/api/me/children")).json();
  },
  async getActiveRequest(): Promise<{ requestId: string; statuses: Record<string, ChildStatus> } | null> {
    const r = await fetch("/api/pickup-requests/active");
    return r.status === 204 ? null : r.json();
  },
  async create(childIds: string[], loc: { latitude: number; longitude: number; accuracy: number }) {
    const r = await fetch("/api/pickup-requests", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ childIds, ...loc }),
    });
    if (!r.ok) throw new UserError((await r.json()).message ?? "Couldn't send your request.");
    return (await r.json()) as { requestId: string; statuses: Record<string, ChildStatus> };
  },
  async get(requestId: string): Promise<Record<string, ChildStatus>> {
    return (await (await fetch(`/api/pickup-requests/${requestId}`)).json()).statuses;
  },
  async cancel(requestId: string) {
    await fetch(`/api/pickup-requests/${requestId}`, { method: "DELETE" });
  },
};

/* ---------- Location helpers ---------- */
function getPosition(): Promise<GeolocationPosition> {
  return new Promise((resolve, reject) => {
    if (!navigator.geolocation) {
      return reject(new UserError("Your device doesn't support location. Please check in at the school office."));
    }
    navigator.geolocation.getCurrentPosition(resolve, (err) => {
      reject(
        new UserError(
          err.code === err.PERMISSION_DENIED
            ? "Location is turned off for this app. Turn it on in your settings, or check in at the school office."
            : "We couldn't get your location. Try again in a more open spot."
        )
      );
    }, { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 }); // fresh fix, used once
  });
}

function distanceMeters(aLat: number, aLng: number, bLat: number, bLng: number) {
  const R = 6371000, rad = (d: number) => (d * Math.PI) / 180;
  const dLat = rad(bLat - aLat), dLng = rad(bLng - aLng);
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(rad(aLat)) * Math.cos(rad(bLat)) * Math.sin(dLng / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(h));
}

/* ---------- Component ---------- */
export default function ParentPickupScreen() {
  const [children, setChildren] = useState<Child[]>([]);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [phase, setPhase] = useState<Phase>("idle");
  const [requestId, setRequestId] = useState<string | null>(null);
  const [statuses, setStatuses] = useState<Record<string, ChildStatus>>({});
  const [error, setError] = useState<string | null>(null);

  // Load children (default: all selected) and resume any active request
  useEffect(() => {
    (async () => {
      const kids = await api.getChildren();
      setChildren(kids);
      setSelected(new Set(kids.map((k) => k.id)));
      const active = await api.getActiveRequest();
      if (active) {
        setRequestId(active.requestId);
        setStatuses(active.statuses);
        setPhase("waiting");
      }
    })().catch(() => setError("Couldn't load your children. Check your connection and reload."));
  }, []);

  // Poll for status while waiting (swap for WebSocket/SSE/push later)
  useEffect(() => {
    if (phase !== "waiting" || !requestId) return;
    const timer = setInterval(async () => {
      try {
        const s = await api.get(requestId);
        setStatuses(s);
        if (Object.values(s).every((v) => v === "released")) setPhase("done");
      } catch { /* transient network error: keep polling */ }
    }, POLL_MS);
    return () => clearInterval(timer);
  }, [phase, requestId]);

  const toggle = (id: string) =>
    setSelected((prev) => {
      const next = new Set(prev);
      next.has(id) ? next.delete(id) : next.add(id);
      return next;
    });

  async function handleImHere() {
    setError(null);
    try {
      setPhase("locating");
      const { coords } = await getPosition();

      if (coords.accuracy > MAX_ACCURACY_METERS) {
        throw new UserError("Your location isn't precise enough. Move to an open area and try again.");
      }
      const dist = distanceMeters(coords.latitude, coords.longitude, SCHOOL.lat, SCHOOL.lng);
      if (dist > GEOFENCE_METERS) {
        throw new UserError("You don't seem to be at the school yet. Tap again when you arrive.");
      }

      setPhase("sending");
      const res = await api.create([...selected], {
        latitude: coords.latitude,
        longitude: coords.longitude,
        accuracy: coords.accuracy,
      });
      setRequestId(res.requestId);
      setStatuses(res.statuses);
      setPhase("waiting");
    } catch (e) {
      setPhase("idle");
      setError(e instanceof UserError ? e.message : "Something went wrong. Please try again.");
    }
  }

  async function handleCancel() {
    if (requestId) await api.cancel(requestId).catch(() => {});
    setRequestId(null);
    setStatuses({});
    setPhase("idle");
  }

  function handleReset() {
    setRequestId(null);
    setStatuses({});
    setPhase("idle");
  }

  const busy = phase === "locating" || phase === "sending";
  const locked = phase === "waiting" || phase === "done" || busy;
  const visibleChildren = phase === "waiting" || phase === "done"
    ? children.filter((c) => c.id in statuses)
    : children;

  return (
    <main className="pickup">
      <style>{css}</style>

      <h1>Pick-up</h1>

      {phase === "done" ? (
        <p className="banner success" role="status">All children have been sent out. Have a great afternoon!</p>
      ) : phase === "waiting" ? (
        <p className="banner info" role="status">The school has been told you're here.</p>
      ) : (
        <p className="sub">Who are you collecting today?</p>
      )}

      <ul className="children">
        {visibleChildren.map((c) => {
          const status = statuses[c.id];
          return (
            <li key={c.id}>
              <label className={`child ${selected.has(c.id) ? "on" : ""} ${locked ? "locked" : ""}`}>
                {!locked && (
                  <input
                    type="checkbox"
                    checked={selected.has(c.id)}
                    onChange={() => toggle(c.id)}
                  />
                )}
                <span className="who">
                  <strong>{c.name}</strong>
                  <small>{c.className}</small>
                </span>
                {status && (
                  <span className={`badge ${status}`}>
                    {status === "released" ? "On their way out ✓" : "Waiting"}
                  </span>
                )}
              </label>
            </li>
          );
        })}
      </ul>

      {error && <p className="banner error" role="alert">{error}</p>}

      {phase === "idle" || busy ? (
        <button
          className="primary"
          onClick={handleImHere}
          disabled={busy || selected.size === 0}
        >
          {phase === "locating" ? "Checking location…" : phase === "sending" ? "Sending…" : "I'm here"}
        </button>
      ) : phase === "waiting" ? (
        <button className="secondary" onClick={handleCancel}>
          Cancel — tapped by mistake / I've left
        </button>
      ) : (
        <button className="secondary" onClick={handleReset}>Done</button>
      )}

      {phase === "idle" && (
        <p className="fine">
          We check your location once, when you tap, to confirm you're at school. It isn't stored or tracked.
        </p>
      )}
    </main>
  );
}

/* ---------- Styles ---------- */
const css = `
.pickup{max-width:480px;margin:0 auto;padding:20px;font-family:system-ui,sans-serif}
.pickup h1{margin:0 0 4px}
.sub{color:#555;margin:0 0 16px}
.children{list-style:none;padding:0;margin:0 0 16px;display:grid;gap:10px}
.child{display:flex;align-items:center;gap:12px;padding:14px;border:2px solid #ddd;border-radius:12px;cursor:pointer;background:#fff}
.child.on{border-color:#2563eb;background:#eff6ff}
.child.locked{cursor:default}
.child input{width:22px;height:22px}
.who{display:flex;flex-direction:column;flex:1}
.who small{color:#666}
.badge{font-size:.85rem;padding:4px 10px;border-radius:999px;background:#fef3c7;color:#92400e}
.badge.released{background:#dcfce7;color:#166534}
.primary,.secondary{width:100%;padding:20px;font-size:1.3rem;font-weight:700;border-radius:14px;border:0;cursor:pointer}
.primary{background:#16a34a;color:#fff}
.primary:disabled{background:#9ca3af;cursor:not-allowed}
.secondary{background:#f3f4f6;color:#111;font-size:1rem;font-weight:600}
.banner{padding:12px 14px;border-radius:10px;margin:0 0 16px}
.banner.info{background:#eff6ff;color:#1e40af}
.banner.success{background:#dcfce7;color:#166534}
.banner.error{background:#fee2e2;color:#991b1b}
.fine{color:#666;font-size:.85rem;text-align:center;margin-top:12px}
`;
```

## Design choices

- **Location is checked once, at tap time.** There's no background tracking and nothing about location is shown in the UI beyond the error messages.
- **The client geofence is only a UX nicety.** The server must recheck the coordinates and accuracy it receives, because a client-side check can be bypassed.
- **Children are released individually.** Siblings in different classes will leave at different times, so each has its own status.
- **It resumes after a reload.** `getActiveRequest` restores the waiting state if the parent closes and reopens the app.
- **Location failures have a human fallback.** Denied permission or a poor GPS fix points the parent to the office rather than leaving them stuck.
- **Cancel is prominent.** Accidental taps and parents who leave early both need a clean way to clear the queue.

## Not included yet

- **Authentication and the parent's profile photo.** The teacher's screen should show it, but the parent screen doesn't need to.
- **Delegates.** A "Someone else is collecting" flow would need a one-time code or an approved-delegate list.
- **Push notifications.** Polling only works while the app is open, so you'll want push or WebSocket for the "sent out" alert.
- **Routine-change notices.** A banner such as "Early dismissal today" would fit above the child list.

Want the teacher's queue screen next, or the backend endpoints and data model these calls assume?
